#pragma once

#include <omni/otel/type2str.h>
#include <carb/cpp/StringView.h>
#include <carb/cpp/Variant.h>
#include <cassert>
#include <cstdint>
#include <cstring>
#include <iosfwd>
#include <type_traits>

namespace omni
{
namespace otel
{

/** Attributes are key-value pairs where the key is a static string (e.g. a string literal),
 *  and the value is a variant. In the case of the carb::cpp::string_view variant, the
 *  \ref Attribute object does not allocate memory and does not own the string. This is because
 *  it is designed for use with instrument functions to specify a set of attributes. In this
 *  context users pass an optional list of attributes, for example:
 *
 *  @code{.cpp}
 *  add(counter, 10, {{"service", "database"}, {"status", 200}});
 *  @endcode
 *
 *  An alternative syntax is supported, which is based on simple structs that define a data
 *  member value. for example:
 *
 *  @code{.cpp}
 *  struct service { carb::cpp::string_view value; };
 *  struct status { int value; };
 *  @endcode
 *
 *  and then:
 *
 *  @code{.cpp}
 *  add(counter, 10, service{"database"}, status{200});
 *  @endcode
 *
 *  which is equivalent to:
 *
 *  @code{.cpp}
 *  add(counter, 10, {{"service", "database"}, {"status", 200}});
 *  @endcode
 *
 *  It is not a good idea to define any members other than the value member.
 *
 *  The struct-based approach effectively reflects the attribute name in the C++ type system,
 *  which has the benefit of preventing bugs caused by mispelling of the attribute name, as
 *  well as allowing trait-based association of additional data, if needed.
 *
 *  When attributes are used with an instrument, e.g. a counter, the set of attributes, together
 *  with the instrument name, identify an individual metric. For example, in the case of a counter
 *  instrument, each unique set of attributes identifies a different count (which in addition can be
 *  aggregated in several different ways).
 *
 *  CARDINALITY WARNING: Take care to not use attributes that can hold arbitrary values, for
 *  example a user name. Failure to pay attention to this can lead to the so-called high
 *  cardinality problem, where the number of unique metrics becomes too large to be manageable.
 */
class Attribute
{
public:
    using VariantType = carb::cpp::variant<bool, int32_t, int64_t, uint32_t, double, carb::cpp::string_view>;

    /** Default constructor creating an empty attribute. */
    constexpr Attribute() noexcept : m_key(""), m_value(carb::cpp::string_view(""))
    {
    }

    /** Constructor for boolean attribute.
     *
     *  @param[in] k The attribute key.
     *  @param[in] v The boolean value.
     */
    constexpr Attribute(carb::cpp::string_view k, bool v) noexcept : m_key(k), m_value(v)
    {
    }

    /** Constructor for 32-bit signed integer attribute.
     *
     *  @param[in] k The attribute key.
     *  @param[in] v The integer value.
     */
    constexpr Attribute(carb::cpp::string_view k, int32_t v) noexcept : m_key(k), m_value(v)
    {
    }

    /** Constructor for 64-bit signed integer attribute.
     *
     *  @param[in] k The attribute key.
     *  @param[in] v The integer value.
     */
    constexpr Attribute(carb::cpp::string_view k, int64_t v) noexcept : m_key(k), m_value(v)
    {
    }

    /** Constructor for 32-bit unsigned integer attribute.
     *
     *  @param[in] k The attribute key.
     *  @param[in] v The unsigned integer value.
     */
    constexpr Attribute(carb::cpp::string_view k, uint32_t v) noexcept : m_key(k), m_value(v)
    {
    }

    /** Constructor for double-precision floating point attribute.
     *
     *  @param[in] k The attribute key.
     *  @param[in] v The double value.
     */
    constexpr Attribute(carb::cpp::string_view k, double v) noexcept : m_key(k), m_value(v)
    {
    }

    /** Constructor for C-style string literal attribute.
     *
     *  @param[in] k The attribute key.
     *  @param[in] v The string literal value.
     */
    template <int N>
    constexpr Attribute(carb::cpp::string_view k, const char (&v)[N]) noexcept : m_key(k), m_value(v)
    {
    }

    /** Constructor for string view attribute.
     *
     *  @param[in] k The attribute key.
     *  @param[in] v The string view value.
     */
    constexpr Attribute(carb::cpp::string_view k, carb::cpp::string_view v) noexcept : m_key(k), m_value(v)
    {
    }

    /** Constructor for struct-based attribute.
     *
     *  @param[in] t A struct with a value member, where the struct type name becomes the key.
     *
     *  @remarks This constructor enables the struct-based syntax where the attribute name
     *           is derived from the type name and the value comes from the struct's value member.
     *
     *  @code{.cpp}
     *  struct service { carb::cpp::string_view value; };
     *  Attribute attr(service{"database"});  // Creates attribute with key "service" and value "database"
     *  @endcode
     */
    template <class T>
    constexpr Attribute(
        T t,
        typename std::enable_if<std::is_constructible<VariantType, decltype(std::declval<T>().value)>::value, int>::type =
            0) noexcept
        : m_key(parse<T>()), m_value(t.value)
    {
    }

    /** Get the attribute key.
     *
     *  @returns The attribute key as a string view.
     */
    constexpr const carb::cpp::string_view& key() const noexcept
    {
        return m_key;
    }

    /** Get the attribute value as a specific type.
     *
     *  @tparam T The type to retrieve the value as.
     *
     *  @returns The attribute value converted to the specified type.
     */
    template <class T>
    constexpr T get() const noexcept
    {
        return carb::cpp::get<T>(m_value);
    }

    /** Get the attribute value as a variant.
     *
     *  @returns The attribute value as a variant type.
     */
    constexpr const VariantType& value() const noexcept
    {
        return m_value;
    }

    template <class CharT, class Traits>
    friend std::basic_ostream<CharT, Traits>& operator<<(std::basic_ostream<CharT, Traits>& os, const Attribute& attr)
    {
        os << attr.m_key << "=";
        carb::cpp::visit([&os](const auto& v) { os << v; }, attr.m_value);
        return os;
    }

private:
    carb::cpp::string_view m_key;
    VariantType m_value;
};

} // namespace otel
} // namespace omni
